W = lambda t: "https://en.wikipedia.org/wiki/" + t.replace(" ", "_")
def M(label, title, kind, date, prec, sentence, src_article, src_section, found, mark_article):
    return {"label": label, "title": title, "kind": kind, "date": date, "precision": prec, "sentence": sentence, "source_label": f"Wikipedia: {src_article}" + (f", {src_section}" if src_section else ""), "source_url": W(src_article) + (("#" + src_section.replace(" ", "_")) if src_section else ""), "found": found, "mark_url": W(mark_article) if mark_article else None, "mark_article": mark_article}
