# verify: the mark article's lead (or the source article) carries the year and, for day or month precision, the month
MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"]
bad = 0
for slug, st in stones.items():
    for i, m in enumerate(st["marks"]):
        m["id"] = f"w{i}"
        art = m["mark_article"] or (m["source_label"].split(": ", 1)[1].split(", ")[0])
        d = get({"action": "parse", "page": art, "prop": "wikitext", "redirects": 1}); txt, _ = clean(d.get("parse", {}).get("wikitext", {}).get("*", ""))
        y = m["date"][:4]; ok_y = y in txt; ok_m = True
        if m["precision"] != "year": mon = MONTHS[int(m["date"][5:7]) - 1]; ok_m = (mon in txt) or (mon[:3] + " " in txt)
        flag = "" if (ok_y and ok_m) else "  <-- CHECK"; bad += not (ok_y and ok_m)
        print(f"{slug[:22]:22s} {m['label'][:30]:30s} {m['date']:10s} {m['precision']:5s} | year in article {ok_y} month {ok_m}{flag}")
out = {"_about": "Engine-found pairs from Wikipedia read as a cited-cause record (docs/discovery_corpus1_v1.md): the stone's article and the articles of laws and institutions that link to it, read for a sentence that names a lasting change with a causal word; each mark dated from the record; the ordering rule applied; every pair shown was confirmed by a person on Oct 4, 2026. A sentence is a reported link, never measured.", "run": "2026-10-04", "stones": stones}
json.dump(out, open("../site/ripples/demo/discovered_wiki.json", "w"), indent=1, ensure_ascii=False)
print("\nstones", len(stones), "marks", sum(len(s["marks"]) for s in stones.values()), "flagged", bad)
